      "path": "src/tools.ts",
      "content": "/**\n * The `unity_*` tool consumers: five model-facing tools over the `unity` CLI.\n * Live-Editor operations (`unity_status`, `unity_list_commands`,\n * `unity_command`, `unity_eval`) parse the CLI's `--format json` envelope;\n * `unity_cli` is the raw escape hatch for everything else (project creation,\n * editor installs, tests, builds).\n * @module unity-plugin/tools\n */\n\nimport type { Context, Volatile } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { ToolRunContext } from '@deepseek-ai/dsh-tools'\nimport type { ConfigWatch } from './live-config.ts'\nimport { runUnity, runUnityJson } from './unity-cli.ts'\nimport type { UnityJsonResult, UnityRunSpec } from './unity-cli.ts'\nimport { UnityShellPool } from './unity-shell.ts'\n\n/**\n * Deployment configuration consumed by the tool consumers. Every field but\n * `env` is volatile: the settings form on the Plugins page edits it live and\n * the tools remount with the new values. `env` carries CI credentials, so it\n * stays in cordis.patch.yml and never rides a settings response.\n */\nexport interface UnityToolsConfig {\n  /** The `unity` executable — a PATH-resolved name or an absolute path. */\n  unityBin: Volatile<string>\n  /** Default Unity project path targeted by live-Editor tools; per-call `projectPath` overrides it. */\n  projectPath: Volatile<string | undefined>\n  /** Cooperative timeout budget for live-Editor tools, in milliseconds. */\n  commandTimeoutMs: Volatile<number>\n  /** Cooperative timeout budget for `unity_cli` (installs, tests, and builds run long), in milliseconds. */\n  cliTimeoutMs: Volatile<number>\n  /** TERM-to-KILL escalation grace for the CLI process tree, in milliseconds. */\n  graceMs: Volatile<number>\n  /** In-memory cap per collected output stream, in bytes. */\n  outputMaxBytes: Volatile<number>\n  /** Explicit environment entries for the CLI (e.g. `UNITY_SERVICE_ACCOUNT_ID`), merged after the subprocess credential scrub. */\n  env: Record<string, string>\n  /** Route the live-Editor tools through a warm `unity shell --protocol ndjson` session instead of one CLI process per call. */\n  warmShell: Volatile<boolean>\n  /** Idle milliseconds after which a warm shell session with no queued work is disposed. */\n  shellIdleMs: Volatile<number>\n}\n\n/** The Config keys the tools consume; a live edit to any of them remounts the tools. */\nconst TOOL_CONFIG_KEYS = [\n  'unityBin', 'projectPath', 'commandTimeoutMs', 'cliTimeoutMs', 'graceMs', 'outputMaxBytes', 'warmShell', 'shellIdleMs',\n] as const\n\n/** One mount's configuration: every volatile field read once. */\ntype UnityToolsSettings = {\n  [K in keyof UnityToolsConfig]: UnityToolsConfig[K] extends Volatile<infer T> ? T : UnityToolsConfig[K]\n}\n\n/** Shared output declaration of the envelope-returning tools. */\nconst ENVELOPE_OUTPUT_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    exitCode: {\n      type: 'integer',\n      required: true,\n      description: 'unity CLI process exit code (0 on success; the envelope carries the failure details otherwise).',\n    },\n    envelope: {\n      type: 'json',\n      required: true,\n      description: 'Parsed unity CLI JSON envelope: { success, command, data, errors, warnings }. Check `success` before relying on `data`.',\n    },\n  },\n} as const\n\n/** Raw output declaration of the `unity_cli` escape hatch. */\nconst RAW_OUTPUT_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    exitCode: {\n      oneOf: [{ type: 'integer' }, { type: 'null' }],\n      required: true,\n      description: 'Process exit code; null when killed by a signal.',\n    },\n    signal: {\n      oneOf: [{ type: 'string' }, { type: 'null' }],\n      required: true,\n      description: 'Terminating signal name; null on normal exit.',\n    },\n    stdout: { type: 'string', required: true },\n    stderr: { type: 'string', required: true },\n    stdoutTruncated: { type: 'boolean', required: true, description: 'True when stdout overflowed the cap and lost its head.' },\n    stderrTruncated: { type: 'boolean', required: true, description: 'True when stderr overflowed the cap and lost its head.' },\n  },\n} as const\n\n/** Optional per-call project override shared by the live-Editor tools. */\nconst PROJECT_PATH_PARAMETER = {\n  type: 'string',\n  description: 'Absolute path of the Unity project whose Editor to target; omit to use the plugin\\'s configured default (or the only running Editor).',\n} as const\n\n/**\n * Register the five `unity_*` tools on `ctx.tools`, remounting them whenever\n * the Loader commits a live edit to a field they consume, as the settings\n * form on the Plugins page writes them. A remount also disposes the warm\n * shell pool, so in-flight warm requests reject and sessions respawn with the\n * new values. The Config schema refuses non-positive timeouts and caps, and\n * the Loader keeps the running values when a candidate fails it, so every\n * mount sees values `defineTool` accepts.\n * @param ctx - registrant context carrying the tool registry and subprocess service.\n * @param config - the deployment's Unity CLI configuration.\n * @param watch - live-edit subscriptions on the plugin entry.\n */\nexport function registerUnityTools(ctx: Context, config: UnityToolsConfig, watch: ConfigWatch): void {\n  let dispose: (() => void) | undefined\n  const mount = (): void => {\n    dispose?.()\n    dispose = mountUnityTools(ctx, {\n      unityBin: config.unityBin.get(),\n      projectPath: config.projectPath.get(),\n      commandTimeoutMs: config.commandTimeoutMs.get(),\n      cliTimeoutMs: config.cliTimeoutMs.get(),\n      graceMs: config.graceMs.get(),\n      outputMaxBytes: config.outputMaxBytes.get(),\n      env: config.env,\n      warmShell: config.warmShell.get(),\n      shellIdleMs: config.shellIdleMs.get(),\n    })\n  }\n  ctx.effect(() => () => {\n    dispose?.()\n    dispose = undefined\n  }, 'unity tools')\n  mount()\n  ctx.effect(() => watch(TOOL_CONFIG_KEYS, mount), 'unity tools: live config')\n}\n\n/**\n * Register the tools and warm pool for one resolved configuration.\n * @param ctx - registrant context carrying the tool registry and subprocess service.\n * @param settings - the configuration this mount runs with.\n * @returns the disposer unregistering the five tools and disposing the pool.\n */\nfunction mountUnityTools(ctx: Context, settings: UnityToolsSettings): () => void {\n  const disposers: (() => void)[] = []\n  /** The calling agent's session cwd, else the harness process cwd. */\n  const cwdOf = (exec: ToolRunContext): string => exec.agent?.session.header.cwd ?? process.cwd()\n\n  /** `--project-path` flags for the effective target project, empty when none is known. */\n  const projectFlags = (override: string | undefined): string[] => {\n    const path = override ?? settings.projectPath\n    return path === undefined ? [] : ['--project-path', path]\n  }\n\n  /** One fully-resolved spec for a JSON-envelope invocation. */\n  const jsonSpec = (exec: ToolRunContext, args: readonly string[]): UnityRunSpec => ({\n    bin: settings.unityBin,\n    args: [...args, '--format', 'json', '--non-interactive'],\n    cwd: cwdOf(exec),\n    env: settings.env,\n    graceMs: settings.graceMs,\n    outputMaxBytes: settings.outputMaxBytes,\n    signal: exec.signal,\n  })\n\n  /** Warm-session pool behind the live-Editor tools; absent when `warmShell` is off. */\n  const pool = settings.warmShell\n    ? new UnityShellPool(ctx, {\n        bin: settings.unityBin,\n        env: settings.env,\n        graceMs: settings.graceMs,\n        outputMaxBytes: settings.outputMaxBytes,\n        idleMs: settings.shellIdleMs,\n      })\n    : undefined\n  if (pool !== undefined) {\n    disposers.push(() => { pool.disposeAll() })\n  }\n\n  /** Run one envelope invocation through the warm session, or per-call when `warmShell` is off. */\n  const runJson = async (exec: ToolRunContext, args: readonly string[]): Promise<UnityJsonResult> => {\n    const spec = jsonSpec(exec, args)\n    if (pool === undefined) return await runUnityJson(ctx, spec)\n    return await pool.runJson(spec.cwd, spec.args, spec.signal)\n  }\n\n  disposers.push(ctx.tools.register(defineTool({\n    name: 'unity_status',\n    description:\n      'Report the Unity Editor instances currently reachable by the unity CLI. '\n      + 'success=false with a STATUS_NO_INSTANCES error means no running Editor has the Pipeline package loaded '\n      + '(open one with unity_cli [\"open\", \"<project>\", \"--args\", \"-automated\"], then poll this until state is \"ready\"). '\n      + 'Run this before live-Editor operations and BEFORE editing scene or asset files directly — '\n      + 'never hand-edit .unity/.prefab/.asset files while a live Editor is reachable.',\n    parameters: {},\n    output: {\n      schema: ENVELOPE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value.envelope, null, 2) }],\n    },\n    timeoutMs: settings.commandTimeoutMs,\n    isConcurrencySafe: () => true,\n    async execute(_args, exec) {\n      return await runJson(exec, ['status'])\n    },\n    presentCall: () => ({ card: 'generic', title: 'Check Unity Editor status', kind: 'read' }),\n  })))\n\n  disposers.push(ctx.tools.register(defineTool({\n    name: 'unity_list_commands',\n    description:\n      'List every command the connected Unity Editor exposes, with full parameter schemas. '\n      + 'The command set is Editor- and project-defined (projects register custom [CliCommand] tools), '\n      + 'so discover names here rather than assuming a command exists before calling unity_command.',\n    parameters: { projectPath: PROJECT_PATH_PARAMETER },\n    output: {\n      schema: ENVELOPE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value.envelope, null, 2) }],\n    },\n    timeoutMs: settings.commandTimeoutMs,\n    isConcurrencySafe: () => true,\n    async execute(args, exec) {\n      return await runJson(exec, ['command', ...projectFlags(args.projectPath)])\n    },\n    presentCall: () => ({ card: 'generic', title: 'List Unity Editor commands', kind: 'read' }),\n  })))\n\n  disposers.push(ctx.tools.register(defineTool({\n    name: 'unity_command',\n    description:\n      'Run one named command on a running Unity Editor — e.g. create_gameobject, find_gameobjects, '\n      + 'get_scene_hierarchy, set_transform, add_component, save_scene, editor_play, screenshot. '\n      + 'Discover available names and their parameters with unity_list_commands first. '\n      + 'Round-trips complete in under a second with no domain reload. '\n      + 'Pass command parameters as raw CLI flag/value elements in `args`, e.g. [\"--name\", \"Player\", \"--x\", \"1.5\"].',\n    parameters: {\n      command: { type: 'string', required: true, description: 'The Editor command name, exactly as unity_list_commands reports it.' },\n      args: {\n        type: 'array',\n        items: { type: 'string' },\n        description: 'Raw CLI arguments appended verbatim after the command name (argv elements, never shell-quoted). Omit for a command with no parameters.',\n      },\n      projectPath: PROJECT_PATH_PARAMETER,\n    },\n    output: {\n      schema: ENVELOPE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value.envelope, null, 2) }],\n    },\n    timeoutMs: settings.commandTimeoutMs,\n    isConcurrencySafe: () => false,\n    async execute(args, exec) {\n      return await runJson(exec, ['command', args.command, ...(args.args ?? []), ...projectFlags(args.projectPath)])\n    },\n    presentCall: args => ({ card: 'generic', title: `Unity: ${args.command}`, kind: 'execute', rawInput: args.args }),\n  })))\n\n  disposers.push(ctx.tools.register(defineTool({\n    name: 'unity_eval',\n    description:\n      'Execute C# in a running Unity Editor and return the result. The code runs inside the Editor process '\n      + 'with full UnityEngine/UnityEditor API access and no domain reload; end with a `return` statement to '\n      + 'produce a value (e.g. `return Application.unityVersion;`). '\n      + 'Requires an Editor whose Pipeline package exposes the eval command (verify with unity_list_commands).',\n    parameters: {\n      code: { type: 'string', required: true, description: 'C# statements to run in the Editor; end with `return <expr>;` to produce output.' },\n      projectPath: PROJECT_PATH_PARAMETER,\n    },\n    output: {\n      schema: ENVELOPE_OUTPUT_SCHEMA,\n      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value.envelope, null, 2) }],\n    },\n    timeoutMs: settings.commandTimeoutMs,\n    isConcurrencySafe: () => false,\n    async execute(args, exec) {\n      return await runJson(exec, ['command', 'eval', args.code, ...projectFlags(args.projectPath)])\n    },\n    presentCall: args => ({ card: 'generic', title: 'Run C# in the Unity Editor', kind: 'execute', rawInput: args.code }),\n  })))\n\n  disposers.push(ctx.tools.register(defineTool({\n    name: 'unity_cli',\n    description:\n      'Run any unity CLI subcommand (the argv after `unity`) — the tool for everything that does not need a '\n      + 'live Editor: [\"projects\", \"create\", ...], [\"templates\", \"list\", \"--editor\", \"lts\"], '\n      + '[\"open\", \"<project>\", \"--args\", \"-automated\"] (always launch the Editor with -automated so interactive dialogs cannot block the agent), '\n      + '[\"pipeline\", \"install\", \"--project-path\", \"<project>\"], [\"editors\", \"--installed\"], [\"test\", ...], '\n      + '[\"build\", ...], [\"auth\", \"status\"], [\"license\", \"status\"], [\"logs\"]. '\n      + 'Runs with --non-interactive, so commands needing interactive input fail loud instead of hanging; '\n      + 'pass \"--yes\"/\"--accept-eula\" explicitly where required. Add \"--format\", \"json\" for machine-readable '\n      + 'output. For live-Editor scene operations prefer unity_command.',\n    parameters: {\n      args: {\n        type: 'array',\n        required: true,\n        items: { type: 'string' },\n        description: 'Argv elements after `unity`, appended verbatim (never shell-quoted).',\n      },\n    },\n    output: {\n      schema: RAW_OUTPUT_SCHEMA,\n      render: (_args, value) => {\n        const status = value.exitCode === null ? `killed by ${value.signal ?? 'signal'}` : `exit code ${value.exitCode}`\n        const parts = [`${status}`]\n        if (value.stdout.length > 0) parts.push(`stdout${value.stdoutTruncated ? ' (truncated to tail)' : ''}:\\n${value.stdout}`)\n        if (value.stderr.length > 0) parts.push(`stderr${value.stderrTruncated ? ' (truncated to tail)' : ''}:\\n${value.stderr}`)\n        return [{ type: 'text', text: parts.join('\\n') }]\n      },\n    },\n    timeoutMs: settings.cliTimeoutMs,\n    isConcurrencySafe: () => false,\n    async execute(args, exec) {\n      const argv = args.args.includes('--non-interactive') ? args.args : [...args.args, '--non-interactive']\n      return await runUnity(ctx, {\n        bin: settings.unityBin,\n        args: argv,\n        cwd: cwdOf(exec),\n        env: settings.env,\n        graceMs: settings.graceMs,\n        outputMaxBytes: settings.outputMaxBytes,\n        signal: exec.signal,\n      })\n    },\n    presentCall: args => ({ card: 'terminal', title: `unity ${args.args.join(' ')}` }),\n  })))\n\n  return () => {\n    for (const dispose of disposers) dispose()\n  }\n}\n"
    },
    {
      "path": "src/unity-shell.ts",
      "content": "/**\n * Warm `unity shell --protocol ndjson` sessions: one long-lived CLI process\n * answering many envelope commands, so live-Editor tools skip the per-call\n * CLI start cost. Requests are `{\"id\",\"argv\"}` JSON lines on stdin; responses\n * are `{\"id\",\"exitCode\",\"envelope\"}` lines on stdout, serialized one at a\n * time (REPL semantics). A request abort kills the whole session tree —\n * one request inside a shared process cannot be cancelled alone — and the\n * next call respawns lazily.\n * @module unity-plugin/unity-shell\n */\n\nimport type { Writable } from 'node:stream'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { SubprocessHandle } from '@deepseek-ai/dsh-subprocess'\nimport type { UnityJson, UnityJsonResult } from './unity-cli.ts'\n\n/** Constant spawn facts shared by every session of one pool. */\nexport interface UnityShellPoolSpec {\n  /** The `unity` executable — a PATH-resolved name or an absolute path. */\n  bin: string\n  /** Explicit environment entries merged after the subprocess seam's credential scrub. */\n  env: Record<string, string>\n  /** TERM-to-KILL escalation grace in milliseconds. */\n  graceMs: number\n  /** Cap on one response line and on the collected stderr tail, in bytes. */\n  outputMaxBytes: number\n  /** Idle milliseconds after which a session with no queued work is disposed. */\n  idleMs: number\n}\n\n/** One queued shell request awaiting its response line. */\ninterface PendingRequest {\n  id: number\n  argv: readonly string[]\n  signal: AbortSignal\n  resolve: (result: UnityJsonResult) => void\n  reject: (error: Error) => void\n  /** Removes this request's abort listener once it settles. */\n  unlisten: () => void\n}\n\n/** Tail of collected stderr kept in a thrown diagnostic, in characters. */\nconst DIAGNOSTIC_TAIL_CHARS = 2000\n\n/** @returns the last {@link DIAGNOSTIC_TAIL_CHARS} characters of `text`. */\nfunction diagnosticTail(text: string): string {\n  return text.length > DIAGNOSTIC_TAIL_CHARS ? text.slice(-DIAGNOSTIC_TAIL_CHARS) : text\n}\n\n/**\n * One live `unity shell` process. Requests are serialized: a request is\n * written only after the previous response line arrived, so response-to-id\n * matching can never interleave. Any protocol breach — a non-JSON line, an\n * id mismatch, an oversized line, process exit — is fatal to the session:\n * every pending request rejects and the pool discards the session.\n */\nclass UnityShellSession {\n  private readonly spec: UnityShellPoolSpec\n  private readonly handle: SubprocessHandle\n  private readonly stdin: Writable\n  private buffer = ''\n  private readonly queue: PendingRequest[] = []\n  private inflight: PendingRequest | undefined\n  private nextId = 1\n  private deadError: Error | undefined\n\n  /** Fires after each settled request that leaves the session idle. */\n  onIdle: (() => void) | undefined\n\n  /**\n   * Spawn the shell process and wire protocol decoding.\n   * @param ctx - plugin context carrying the `subprocess` service.\n   * @param spec - constant spawn facts.\n   * @param cwd - working directory of the shell process.\n   */\n  constructor(ctx: Context, spec: UnityShellPoolSpec, cwd: string) {\n    this.spec = spec\n    this.handle = ctx.subprocess.spawn({\n      argv: [spec.bin, 'shell', '--protocol', 'ndjson', '--non-interactive', '--no-banner', '--quiet'],\n      cwd,\n      stdio: {\n        stdin: 'pipe',\n        stdout: 'pipe',\n        stderr: { maxBytes: spec.outputMaxBytes },\n      },\n      graceMs: spec.graceMs,\n      env: spec.env,\n    })\n    // 'pipe' dispositions guarantee both streams on the handle.\n    const stdout = this.handle.stdout\n    const stdin = this.handle.stdin\n    if (stdout === undefined || stdin === undefined) {\n      this.handle.terminate()\n      throw new Error('unity shell spawn returned no piped stdio (subprocess provider contract breach)')\n    }\n    this.stdin = stdin\n    // A 'pipe' disposition hands the raw streams to the caller, so the seam\n    // attaches no 'error' listener of its own — and a stream that emits\n    // 'error' unlistened throws out of the event loop. Both errors mean the\n    // child is gone or dying, which `handle.done` reports authoritatively\n    // below; swallowing them here is the same deferral `pump` makes for a\n    // failed write, and keeps a dying session from taking the host down.\n    stdin.on('error', () => {})\n    stdout.on('error', () => {})\n    stdout.setEncoding('utf8')\n    stdout.on('data', (chunk: string) => { this.onStdout(chunk) })\n    this.handle.done.then(\n      (outcome) => {\n        const exit = outcome.exitCode === null ? `killed by ${outcome.signal ?? 'signal'}` : `exit code ${outcome.exitCode}`\n        this.fail(new Error(\n          `unity shell session ended (${exit}). If this unity CLI version lacks \\`unity shell\\`, `\n          + `set warmShell: false in the unity-plugin config.${this.stderrTailSuffix()}`,\n        ))\n      },\n      (error: unknown) => {\n        this.fail(new Error(\n          `unity shell failed to start (is ${JSON.stringify(this.spec.bin)} installed and on PATH? `\n          + `See https://docs.unity3d.com/hub/manual/CLI.html)${this.stderrTailSuffix()}`,\n          { cause: error },\n        ))\n      },\n    )\n  }\n\n  /** True once the session rejected and must be discarded. */\n  get dead(): boolean {\n    return this.deadError !== undefined\n  }\n\n  /** True while no request is in flight or queued. */\n  get idle(): boolean {\n    return this.inflight === undefined && this.queue.length === 0\n  }\n\n  /**\n   * Run one envelope command through the warm process.\n   * @param argv - CLI argv after `unity`, sent verbatim as the request's argv array.\n   * @param signal - abort (tool timeout or caller cancellation); aborting an in-flight request kills the session.\n   * @returns the response's exit code and parsed envelope.\n   */\n  request(argv: readonly string[], signal: AbortSignal): Promise<UnityJsonResult> {\n    return new Promise<UnityJsonResult>((resolve, reject) => {\n      if (this.deadError !== undefined) {\n        reject(this.deadError)\n        return\n      }\n      if (signal.aborted) {\n        reject(new Error('unity shell request was aborted before start (tool timeout or caller cancellation)'))\n        return\n      }\n      const pending: PendingRequest = { id: this.nextId++, argv, signal, resolve, reject, unlisten: () => {} }\n      const onAbort = (): void => { this.abort(pending) }\n      signal.addEventListener('abort', onAbort, { once: true })\n      pending.unlisten = () => { signal.removeEventListener('abort', onAbort) }\n      this.queue.push(pending)\n      this.pump()\n    })\n  }\n\n  /** Idempotently end the session: close stdin, reject outstanding requests, and start the TERM-to-KILL escalation. */\n  dispose(): void {\n    try {\n      this.stdin.end()\n    } catch {\n      // The pipe may already be destroyed by process exit; fail() below settles the tree either way.\n    }\n    this.fail(new Error('unity shell session was disposed'))\n  }\n\n  /** Write the next queued request when none is in flight. */\n  private pump(): void {\n    if (this.deadError !== undefined || this.inflight !== undefined) return\n    const next = this.queue.shift()\n    if (next === undefined) return\n    this.inflight = next\n    try {\n      this.stdin.write(`${JSON.stringify({ id: next.id, argv: next.argv })}\\n`, () => {\n        // A write error means the child is gone or dying; handle.done settles\n        // next with the authoritative spawn/exit error, which fails the\n        // session. Failing here first would mask that error (e.g. reporting\n        // EPIPE for a missing binary).\n      })\n    } catch {\n      // A destroyed stdin stream throws synchronously; same deferral as above.\n    }\n  }\n\n  /** Decode complete response lines from a stdout chunk. */\n  private onStdout(chunk: string): void {\n    if (this.deadError !== undefined) return\n    this.buffer += chunk\n    let newline = this.buffer.indexOf('\\n')\n    while (newline !== -1) {\n      const line = this.buffer.slice(0, newline)\n      this.buffer = this.buffer.slice(newline + 1)\n      if (line.trim().length > 0) this.onLine(line)\n      if (this.deadError !== undefined) return\n      newline = this.buffer.indexOf('\\n')\n    }\n    if (this.buffer.length > this.spec.outputMaxBytes) {\n      this.fail(new Error(\n        `unity shell response exceeded the configured outputMaxBytes cap (${this.spec.outputMaxBytes}); raise it in the plugin config`,\n      ))\n    }\n  }\n\n  /** Match one response line to the in-flight request and settle it. */\n  private onLine(line: string): void {\n    let parsed: UnityJson\n    try {\n      parsed = JSON.parse(line) as UnityJson\n    } catch {\n      this.fail(new Error(`unity shell wrote a non-JSON line: ${diagnosticTail(line)}`))\n      return\n    }\n    const inflight = this.inflight\n    if (\n      typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)\n      || inflight === undefined || parsed.id !== inflight.id\n      || typeof parsed.exitCode !== 'number' || !('envelope' in parsed)\n    ) {\n      this.fail(new Error(`unity shell wrote an unexpected response line: ${diagnosticTail(line)}`))\n      return\n    }\n    this.inflight = undefined\n    inflight.unlisten()\n    inflight.resolve({ exitCode: parsed.exitCode, envelope: parsed.envelope })\n    this.pump()\n    if (this.idle) this.onIdle?.()\n  }\n\n  /** Settle one request's abort: dequeue a waiting request, kill the session for an in-flight one. */\n  private abort(pending: PendingRequest): void {\n    const queued = this.queue.indexOf(pending)\n    if (queued !== -1) {\n      this.queue.splice(queued, 1)\n      pending.unlisten()\n      pending.reject(new Error('unity shell request was aborted (tool timeout or caller cancellation)'))\n      if (this.idle) this.onIdle?.()\n      return\n    }\n    if (this.inflight === pending) {\n      this.fail(new Error('unity shell request was aborted (tool timeout or caller cancellation); the warm session was killed and will respawn on the next call'))\n    }\n  }\n\n  /** Mark the session dead, reject everything outstanding, and terminate the tree. */\n  private fail(error: Error): void {\n    if (this.deadError !== undefined) return\n    this.deadError = error\n    const outstanding = [...(this.inflight === undefined ? [] : [this.inflight]), ...this.queue]\n    this.inflight = undefined\n    this.queue.length = 0\n    for (const pending of outstanding) {\n      pending.unlisten()\n      pending.reject(error)\n    }\n    this.handle.terminate()\n    this.onIdle?.()\n  }\n\n  /** @returns a `\\nstderr tail:` suffix for diagnostics, empty when nothing was captured. */\n  private stderrTailSuffix(): string {\n    const tail = this.handle.collected.stderr?.readFrom(0).text ?? ''\n    return tail.length === 0 ? '' : `\\nstderr tail:\\n${diagnosticTail(tail)}`\n  }\n}\n\n/**\n * Warm-session pool: at most one live shell per working directory, created\n * lazily, replaced after death on the next request, and disposed after\n * {@link UnityShellPoolSpec.idleMs} without queued work. The pool never\n * falls back to cold spawns itself — a dead session's error surfaces to the\n * caller, keeping degraded environments loud.\n */\nexport class UnityShellPool {\n  private readonly ctx: Context\n  private readonly spec: UnityShellPoolSpec\n  private readonly sessions = new Map<string, { session: UnityShellSession, idleTimer: NodeJS.Timeout | undefined }>()\n\n  /**\n   * Build the pool.\n   * @param ctx - plugin context carrying the `subprocess` service.\n   * @param spec - constant spawn facts shared by every session.\n   */\n  constructor(ctx: Context, spec: UnityShellPoolSpec) {\n    this.ctx = ctx\n    this.spec = spec\n  }\n\n  /**\n   * Run one envelope command through the cwd's warm session, spawning or\n   * respawning it as needed.\n   * @param cwd - working directory keying (and hosting) the session.\n   * @param argv - CLI argv after `unity`, sent verbatim.\n   * @param signal - abort forwarded to the request (and, in flight, the session).\n   * @returns the response's exit code and parsed envelope.\n   */\n  async runJson(cwd: string, argv: readonly string[], signal: AbortSignal): Promise<UnityJsonResult> {\n    let entry = this.sessions.get(cwd)\n    if (entry === undefined || entry.session.dead) {\n      if (entry !== undefined) this.drop(cwd)\n      const session = new UnityShellSession(this.ctx, this.spec, cwd)\n      entry = { session, idleTimer: undefined }\n      session.onIdle = () => { this.onSessionIdle(cwd) }\n      this.sessions.set(cwd, entry)\n    }\n    if (entry.idleTimer !== undefined) {\n      clearTimeout(entry.idleTimer)\n      entry.idleTimer = undefined\n    }\n    return await entry.session.request(argv, signal)\n  }\n\n  /** Dispose every session; the pool remains usable and respawns on demand. */\n  disposeAll(): void {\n    for (const cwd of [...this.sessions.keys()]) this.drop(cwd)\n  }\n\n  /** Arm (or run) the idle reaper for one session that just went quiet. */\n  private onSessionIdle(cwd: string): void {\n    const entry = this.sessions.get(cwd)\n    if (entry === undefined) return\n    if (entry.session.dead) {\n      this.drop(cwd)\n      return\n    }\n    if (entry.idleTimer !== undefined) clearTimeout(entry.idleTimer)\n    entry.idleTimer = setTimeout(() => {\n      const current = this.sessions.get(cwd)\n      if (current?.session.idle === true || current?.session.dead === true) this.drop(cwd)\n    }, this.spec.idleMs)\n    entry.idleTimer.unref()\n  }\n\n  /** Remove and dispose one session. */\n  private drop(cwd: string): void {\n    const entry = this.sessions.get(cwd)\n    if (entry === undefined) return\n    this.sessions.delete(cwd)\n    if (entry.idleTimer !== undefined) clearTimeout(entry.idleTimer)\n    entry.session.dispose()\n  }\n}\n"
    },
    {
      "path": "src/unity-cli.ts",
      "content": "/**\n * Spawn-backed `unity` CLI execution. Runs a plain argv vector through the\n * harness subprocess seam with bounded collected output, plus the\n * `--format json` variant whose stdout is one CLI JSON envelope.\n * @module unity-plugin/unity-cli\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { SubprocessHandle, SubprocessOutcome, SubprocessSpawnSpec } from '@deepseek-ai/dsh-subprocess'\n\n/** Lossless JSON value, the parse result of one CLI `--format json` stdout. */\nexport type UnityJson = null | boolean | number | string | UnityJson[] | { [key: string]: UnityJson }\n\n/** One fully-resolved `unity` CLI invocation. */\nexport interface UnityRunSpec {\n  /** The `unity` executable — a PATH-resolved name or an absolute path. */\n  bin: string\n  /** Arguments after the executable; argv elements, never shell-interpreted. */\n  args: readonly string[]\n  /** Working directory for the CLI process. */\n  cwd: string\n  /** Explicit environment entries merged after the subprocess seam's credential scrub. */\n  env: Record<string, string>\n  /** TERM-to-KILL escalation grace in milliseconds. */\n  graceMs: number\n  /** In-memory tail cap per output stream, in bytes. */\n  outputMaxBytes: number\n  /** Abort signal forwarded to the process tree (tool timeout or caller cancellation). */\n  signal: AbortSignal\n}\n\n/** Exit and output facts of one completed `unity` CLI run. */\nexport interface UnityRunResult {\n  /** Exit code; null when the process died from a signal. */\n  exitCode: number | null\n  /** Terminating signal name; null on normal exit. */\n  signal: string | null\n  /** Collected stdout (the retained tail when truncated). */\n  stdout: string\n  /** Collected stderr (the retained tail when truncated). */\n  stderr: string\n  /** True when stdout overflowed the cap and lost its head. */\n  stdoutTruncated: boolean\n  /** True when stderr overflowed the cap and lost its head. */\n  stderrTruncated: boolean\n}\n\n/** Exit code plus the parsed envelope of one `--format json` run. */\nexport interface UnityJsonResult {\n  /** Exit code of the CLI process (non-zero envelopes still parse). */\n  exitCode: number\n  /** Parsed CLI envelope: `{ success, command, data, errors, warnings }`. */\n  envelope: UnityJson\n}\n\n/**\n * Run one `unity` CLI invocation to completion and collect both streams.\n * Throws only for process-level failures (spawn failure, abort); a non-zero\n * exit code is a result, not an error — the CLI reports failures in-band.\n * @param ctx - plugin context carrying the `subprocess` service.\n * @param spec - the fully-resolved invocation.\n * @returns exit facts and the collected output tails.\n */\nexport async function runUnity(ctx: Context, spec: UnityRunSpec): Promise<UnityRunResult> {\n  if (spec.signal.aborted) {\n    throw new Error('unity CLI run was aborted before start (tool timeout or caller cancellation)')\n  }\n  let handle: SubprocessHandle\n  try {\n    handle = ctx.subprocess.spawn({\n      argv: [spec.bin, ...spec.args],\n      cwd: spec.cwd,\n      stdio: {\n        stdin: 'ignore',\n        stdout: { maxBytes: spec.outputMaxBytes },\n        stderr: { maxBytes: spec.outputMaxBytes },\n      },\n      graceMs: spec.graceMs,\n      signal: spec.signal,\n      env: spec.env,\n    } satisfies SubprocessSpawnSpec)\n  } catch (error: unknown) {\n    throw new Error(`unity CLI failed to start — is ${JSON.stringify(spec.bin)} installed and on PATH?`, { cause: error })\n  }\n  let outcome: SubprocessOutcome\n  try {\n    outcome = await handle.done\n  } catch (error: unknown) {\n    throw new Error(\n      `unity CLI failed to start (is ${JSON.stringify(spec.bin)} installed and on PATH? `\n      + 'See https://docs.unity3d.com/hub/manual/CLI.html)',\n      { cause: error },\n    )\n  }\n  const stdout = handle.collected.stdout?.readFrom(0)\n  const stderr = handle.collected.stderr?.readFrom(0)\n  if (spec.signal.aborted) {\n    throw new Error('unity CLI run was aborted (tool timeout or caller cancellation)')\n  }\n  return {\n    exitCode: outcome.exitCode,\n    signal: outcome.signal,\n    stdout: stdout?.text ?? '',\n    stderr: stderr?.text ?? '',\n    stdoutTruncated: stdout?.lossy ?? false,\n    stderrTruncated: stderr?.lossy ?? false,\n  }\n}\n\n/** Tail of a stream kept in a thrown diagnostic, in characters. */\nconst DIAGNOSTIC_TAIL_CHARS = 2000\n\n/** @returns the last {@link DIAGNOSTIC_TAIL_CHARS} characters of `text`. */\nfunction diagnosticTail(text: string): string {\n  return text.length > DIAGNOSTIC_TAIL_CHARS ? text.slice(-DIAGNOSTIC_TAIL_CHARS) : text\n}\n\n/**\n * Run one `unity ... --format json` invocation and parse its stdout envelope.\n * The caller appends `--format json` itself; this helper owns only the exit\n * and parse checks. Throws when the process was killed by a signal, stdout\n * overflowed the cap (the envelope would be incomplete), or stdout is not JSON.\n * @param ctx - plugin context carrying the `subprocess` service.\n * @param spec - the fully-resolved invocation, already carrying `--format json`.\n * @returns the exit code and the parsed envelope.\n */\nexport async function runUnityJson(ctx: Context, spec: UnityRunSpec): Promise<UnityJsonResult> {\n  const result = await runUnity(ctx, spec)\n  if (result.exitCode === null) {\n    throw new Error(`unity CLI was killed by signal ${result.signal ?? '(unknown)'}; stderr tail:\\n${diagnosticTail(result.stderr)}`)\n  }\n  if (result.stdoutTruncated) {\n    throw new Error('unity CLI JSON output exceeded the configured outputMaxBytes cap; raise it in the plugin config')\n  }\n  let envelope: UnityJson\n  try {\n    envelope = JSON.parse(result.stdout) as UnityJson\n  } catch {\n    throw new Error(\n      `unity CLI did not return JSON (exit code ${result.exitCode}).\\n`\n      + `stdout tail:\\n${diagnosticTail(result.stdout)}\\nstderr tail:\\n${diagnosticTail(result.stderr)}`,\n    )\n  }\n  return { exitCode: result.exitCode, envelope }\n}\n"
    },
    {
      "path": "src/skill.ts",
      "content": "/**\n * Skill roots. Mounts the dsh filesystem skill provider twice: over this\n * package's `assets/skills/` directory (the plugin's own `unity-workflow`\n * and `unity-asset-store` skills), and — once the download settles — over\n * the cached Unity skill collection fetched at activation from\n * github.com/Unity-Technologies/skills (see unity-skills-fetch.ts). Reusing\n * the filesystem provider keeps SKILL.md frontmatter, bundle-directory\n * resources, and invocation-policy conventions identical to user- and\n * project-level skills; the `bundled` source rank keeps every mounted skill\n * overridable by a same-named project- or user-level skill. The collection's\n * repository, ref, and cache directory are live-editable.\n * @module unity-plugin/skill\n */\n\nimport { fileURLToPath } from 'node:url'\nimport type { Context, Fiber, Volatile } from '@deepseek-ai/cordis'\nimport * as skillFilesystem from '@deepseek-ai/dsh-skill-filesystem'\nimport { ensureUnitySkills } from './unity-skills-fetch.ts'\nimport type { UnitySkillsFetchSpec } from './unity-skills-fetch.ts'\nimport type { ConfigWatch } from './live-config.ts'\n\n/** Absolute path of the plugin's own skill root shipped in the package. */\nconst BUNDLED_SKILL_DIR = fileURLToPath(new URL('../assets/skills/', import.meta.url))\n\n/** The skill-facing subset of the plugin configuration; all live-editable. */\nexport interface UnitySkillsConfig {\n  /** Whether to download the Unity skill collection at all. */\n  unitySkillsDownload: Volatile<boolean>\n  /** Git URL of the Unity skills repository; the empty string disables the download. */\n  unitySkillsRepo: Volatile<string>\n  /** Commit SHA, tag, or branch of the Unity skills to fetch. */\n  unitySkillsRef: Volatile<string>\n  /** Cache directory override for the downloaded collection. */\n  unitySkillsCacheDir: Volatile<string | undefined>\n  /** TERM-to-KILL escalation grace for the fetch's git processes, in milliseconds. */\n  graceMs: Volatile<number>\n}\n\n/** The Config keys selecting the downloaded collection; a live edit to any of them swaps it. */\nconst SKILLS_CONFIG_KEYS = ['unitySkillsDownload', 'unitySkillsRepo', 'unitySkillsRef', 'unitySkillsCacheDir'] as const\n\n/**\n * Mount the plugin's own bundled skills immediately, then fetch (or reuse\n * the cached copy of) the Unity skill collection and mount it as a second\n * provider. A failed download degrades to the bundled root alone, with the\n * cause logged. A live edit to the download switch, repository, ref, or\n * cache directory aborts any in-flight fetch, unmounts the collection, and\n * fetches the new one; plugin teardown aborts an in-flight fetch.\n * @param ctx - context whose `skills` service is ready.\n * @param config - the skill-facing plugin configuration.\n * @param watch - live-edit subscriptions on the plugin entry.\n */\nexport function registerUnitySkills(ctx: Context, config: UnitySkillsConfig, watch: ConfigWatch): void {\n  ctx.plugin(skillFilesystem, {\n    providerName: 'unity-plugin',\n    includeDefaultRoots: false,\n    bundledSkillDir: BUNDLED_SKILL_DIR,\n    watch: false,\n  })\n\n  let dispose: (() => void) | undefined\n  // Fetches share the cache and its staging path, and an abort stops only the\n  // git steps, so each fetch starts after the one it replaces has settled.\n  let settled: Promise<void> = Promise.resolve()\n  const mount = (): void => {\n    dispose?.()\n    const upstream = mountUpstreamSkills(ctx, {\n      // An empty repo is the switch cordis.patch.yml has always offered.\n      repo: config.unitySkillsDownload.get() ? config.unitySkillsRepo.get() : '',\n      ref: config.unitySkillsRef.get(),\n      cacheDir: config.unitySkillsCacheDir.get(),\n      graceMs: config.graceMs.get(),\n    }, settled)\n    dispose = upstream.dispose\n    settled = upstream.settled\n  }\n  ctx.effect(() => () => {\n    dispose?.()\n    dispose = undefined\n  }, 'unity-plugin: upstream skills')\n  mount()\n  ctx.effect(() => watch(SKILLS_CONFIG_KEYS, mount), 'unity-plugin: skills live config')\n}\n\n/**\n * Fetch one Unity skill collection and mount it once the download settles.\n * @param ctx - context whose `skills` service is ready.\n * @param spec - the collection to fetch, without its abort signal.\n * @param after - settlement of the fetch this one replaces.\n * @returns the disposer aborting the fetch and unmounting the collection, and this fetch's settlement.\n */\nfunction mountUpstreamSkills(\n  ctx: Context,\n  spec: Omit<UnitySkillsFetchSpec, 'signal'>,\n  after: Promise<void>,\n): { dispose: () => void, settled: Promise<void> } {\n  const abort = new AbortController()\n  let provider: Fiber | undefined\n  const settled = after.then(async () => {\n    if (abort.signal.aborted) return undefined\n    return await ensureUnitySkills(ctx, { ...spec, signal: abort.signal })\n  }).then((cacheDir) => {\n    if (cacheDir === undefined || abort.signal.aborted) return\n    provider = ctx.plugin(skillFilesystem, {\n      providerName: 'unity-plugin-upstream',\n      includeDefaultRoots: false,\n      bundledSkillDir: cacheDir,\n      watch: false,\n    })\n  }).catch((error: unknown) => {\n    // ensureUnitySkills contains fetch failures; this guards the mount itself\n    // (e.g. a context disposed between the settle check and the plugin call).\n    ctx.logger.warn('unity-plugin: mounting the downloaded Unity skills failed', error)\n  })\n  return {\n    dispose: () => {\n      abort.abort()\n      void provider?.dispose()\n    },\n    settled,\n  }\n}\n"
    },
    {
      "path": "src/unity-skills-fetch.ts",
      "content": "/**\n * Downloaded Unity skill collection: a shallow git fetch of one configured\n * ref of github.com/Unity-Technologies/skills into a local cache directory,\n * run through the harness subprocess seam at plugin activation. Content is\n * fetched once per configured ref (a marker file records it); changing the\n * ref re-fetches, and a branch name snapshots that branch at first fetch.\n * A failed fetch keeps an existing cache of any ref; with no cache the\n * caller degrades to the plugin's own bundled skills.\n * @module unity-plugin/unity-skills-fetch\n */\n\nimport { homedir, tmpdir } from 'node:os'\nimport { join } from 'node:path'\nimport { cp, mkdir, mkdtemp, readFile, readdir, rename, rm, writeFile } from 'node:fs/promises'\nimport type { Context } from '@deepseek-ai/cordis'\n\n/** Pinned upstream commit fetched by default; known good under dsh's strict frontmatter parser (with {@link fixKnownFrontmatter}). */\nexport const UNITY_SKILLS_DEFAULT_REF = '87fac23d66a1f44f5e06c2935eccce0b40b9715a'\n\n/** Upstream repository fetched by default. */\nexport const UNITY_SKILLS_DEFAULT_REPO = 'https://github.com/Unity-Technologies/skills'\n\n/** Fetch configuration, resolved from the plugin config. */\nexport interface UnitySkillsFetchSpec {\n  /** Git URL of the skills repository; the empty string disables the download entirely. */\n  repo: string\n  /** Commit SHA, tag, or branch to fetch. */\n  ref: string\n  /** Cache directory override; defaults to `<dshHome>/cache/unity-plugin/unity-skills`. */\n  cacheDir?: string | undefined\n  /** TERM-to-KILL escalation grace for the git processes, in milliseconds. */\n  graceMs: number\n  /** Overall abort for the fetch (plugin teardown). */\n  signal: AbortSignal\n}\n\n/** @returns the sibling marker file recording which ref the cache came from (outside the mounted root, so the skill scan never sees it). */\nfunction refMarkerPath(cacheDir: string): string {\n  return `${cacheDir}.ref`\n}\n\n/** Time budget for the whole fetch, in milliseconds; generous for a shallow fetch of a docs repository. */\nconst FETCH_TIMEOUT_MS = 300_000\n\n/** @returns the dsh config root (`$DSH_HOME` or `~/.dsh`), mirroring `@deepseek-ai/dsh-home-paths`. */\nfunction dshHome(): string {\n  const fromEnv = process.env.DSH_HOME\n  return fromEnv !== undefined && fromEnv !== '' ? fromEnv : join(homedir(), '.dsh')\n}\n\n/** @returns the effective cache directory for `spec`. */\nexport function unitySkillsCacheDir(spec: Pick<UnitySkillsFetchSpec, 'cacheDir'>): string {\n  return spec.cacheDir ?? join(dshHome(), 'cache', 'unity-plugin', 'unity-skills')\n}\n\n/**\n * Run one git invocation through the subprocess seam and throw on failure.\n * @param ctx - plugin context carrying the `subprocess` service.\n * @param spec - fetch configuration (grace and abort).\n * @param args - git argv after the executable.\n * @param cwd - working directory for the git process.\n */\nasync function runGit(ctx: Context, spec: UnitySkillsFetchSpec, signal: AbortSignal, args: readonly string[], cwd: string): Promise<void> {\n  const handle = ctx.subprocess.spawn({\n    argv: ['git', ...args],\n    cwd,\n    stdio: { stdin: 'ignore', stdout: { maxBytes: 65_536 }, stderr: { maxBytes: 65_536 } },\n    graceMs: spec.graceMs,\n    signal,\n  })\n  const outcome = await handle.done\n  if (outcome.exitCode !== 0) {\n    const stderr = handle.collected.stderr?.readFrom(0).text ?? ''\n    const exit = outcome.exitCode === null ? `killed by ${outcome.signal ?? 'signal'}` : `exit code ${outcome.exitCode}`\n    throw new Error(`git ${args[0]} failed (${exit})${stderr === '' ? '' : `:\\n${stderr.slice(-2000)}`}`)\n  }\n}\n\n/**\n * Re-apply the known upstream frontmatter defect fix: the\n * `physics-3d-collision` description is a plain YAML scalar containing `: `\n * sequences, which dsh's spec-compliant parser rejects (the skill would\n * warn-and-skip). Rewritten as a `>-` folded block scalar; text unchanged.\n * A ref where upstream has fixed the file no longer matches and is left alone.\n * @param skillsDir - checked-out skills directory to fix in place.\n */\nasync function fixKnownFrontmatter(skillsDir: string): Promise<void> {\n  const file = join(skillsDir, 'physics-3d-collision', 'SKILL.md')\n  let text: string\n  try {\n    text = await readFile(file, 'utf8')\n  } catch {\n    return\n  }\n  const match = /^description: (?![>|'\"])(.*: .*)$/m.exec(text)\n  if (match === null || match[1] === undefined) return\n  await writeFile(file, text.replace(match[0], `description: >-\\n  ${match[1]}`))\n}\n\n/**\n * Ensure the cache holds the configured ref's skills, fetching when needed.\n * @param ctx - plugin context carrying the `subprocess` service.\n * @param spec - fetch configuration.\n * @returns the cache directory to mount, or undefined when the download is\n * disabled or failed with no prior cache to fall back to.\n */\nexport async function ensureUnitySkills(ctx: Context, spec: UnitySkillsFetchSpec): Promise<string | undefined> {\n  if (spec.repo === '') return undefined\n  const cacheDir = unitySkillsCacheDir(spec)\n  let cachedRef: string | undefined\n  try {\n    cachedRef = (await readFile(refMarkerPath(cacheDir), 'utf8')).trim()\n  } catch {\n    cachedRef = undefined\n  }\n  if (cachedRef === spec.ref) return cacheDir\n  try {\n    await fetchInto(ctx, spec, cacheDir)\n    return cacheDir\n  } catch (error: unknown) {\n    if (cachedRef !== undefined) {\n      ctx.logger.warn(`unity-plugin: fetching Unity skills ${spec.ref} failed; keeping the cached ${cachedRef}`, error)\n      return cacheDir\n    }\n    ctx.logger.warn(\n      'unity-plugin: fetching the Unity skill collection failed and no cache exists; '\n      + 'continuing with only the plugin\\'s own bundled skills (is git installed and the network reachable?)',\n      error,\n    )\n    return undefined\n  }\n}\n\n/**\n * Shallow-fetch the ref and atomically replace the cache with its `skills/`\n * directory plus the ref marker.\n * @param ctx - plugin context carrying the `subprocess` service.\n * @param spec - fetch configuration.\n * @param cacheDir - final cache directory.\n */\nasync function fetchInto(ctx: Context, spec: UnitySkillsFetchSpec, cacheDir: string): Promise<void> {\n  await mkdir(join(cacheDir, '..'), { recursive: true })\n  const clone = await mkdtemp(join(tmpdir(), 'unity-plugin-skills-'))\n  const stage = `${cacheDir}.stage-${process.pid}`\n  // One deadline over the whole fetch, composed with the plugin-teardown abort.\n  const deadline = AbortSignal.any([spec.signal, AbortSignal.timeout(FETCH_TIMEOUT_MS)])\n  try {\n    await runGit(ctx, spec, deadline, ['init', '--quiet', clone], clone)\n    await runGit(ctx, spec, deadline, ['remote', 'add', 'origin', spec.repo], clone)\n    await runGit(ctx, spec, deadline, ['fetch', '--quiet', '--depth', '1', 'origin', spec.ref], clone)\n    await runGit(ctx, spec, deadline, ['checkout', '--quiet', '--detach', 'FETCH_HEAD'], clone)\n    const skillsDir = join(clone, 'skills')\n    const entries = await readdir(skillsDir).catch(() => [])\n    if (entries.length === 0) {\n      throw new Error(`ref ${spec.ref} of ${spec.repo} has no skills/ directory`)\n    }\n    await fixKnownFrontmatter(skillsDir)\n    await rm(stage, { recursive: true, force: true })\n    await cp(skillsDir, stage, { recursive: true })\n    await rm(refMarkerPath(cacheDir), { force: true })\n    await rm(cacheDir, { recursive: true, force: true })\n    await rename(stage, cacheDir)\n    await writeFile(refMarkerPath(cacheDir), `${spec.ref}\\n`)\n  } finally {\n    await rm(clone, { recursive: true, force: true }).catch(() => {})\n    await rm(stage, { recursive: true, force: true }).catch(() => {})\n  }\n}\n"
    },
    {
      "path": "src/live-config.ts",
      "content": "/**\n * Live configuration edits, routed by the top-level Config keys they touch.\n * The Loader commits a volatile-only edit into the running `Volatile`\n * references and announces it once, through `loader/volatile-update`, to\n * listeners on the plugin entry's own fiber only — a context from\n * `ctx.inject` is a child fiber and never hears it. The watcher is therefore\n * created on the entry context in `apply`, and the tools and skills halves\n * subscribe to the keys they consume.\n * @module unity-plugin/live-config\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\n// Type-only: the Loader's `loader/volatile-update` event merge.\nimport type {} from '@deepseek-ai/cordis-plugin-loader'\n\n/**\n * Subscribe to live edits of some top-level Config keys.\n * @param keys - the keys the listener consumes.\n * @param listener - invoked once per edit touching any of them, after the new values are committed.\n * @returns the disposer removing this subscription.\n */\nexport type ConfigWatch = (keys: readonly string[], listener: () => void) => () => void\n\n/**\n * Listen for live edits on the plugin entry's context.\n * @param ctx - the plugin entry's own context (the one `apply` receives).\n * @returns the key-routed subscription function.\n */\nexport function watchConfig(ctx: Context): ConfigWatch {\n  const subscriptions = new Set<{ keys: ReadonlySet<string>, listener: () => void }>()\n  ctx.on('loader/volatile-update', (paths) => {\n    const touched = new Set(paths.map(path => path[0]))\n    for (const subscription of [...subscriptions]) {\n      if ([...subscription.keys].some(key => touched.has(key))) subscription.listener()\n    }\n  })\n  return (keys, listener) => {\n    const subscription = { keys: new Set(keys), listener }\n    subscriptions.add(subscription)\n    return () => { subscriptions.delete(subscription) }\n  }\n}\n"
    }
  ],
